/**
 * @param {{ id: string, size: number }[]} items
 * @param {number} slotSize
 * @returns {string[][]} the ids of the items in each slot
 */
export function packSlots(items, slotSize) {
	const ordered = [...items].sort((x, y) =>
		y.size !== x.size ? y.size - x.size : x.id < y.id ? -1 : x.id > y.id ? 1 : 0
	);
	const slots = [];
	for (const item of ordered) {
		if (item.size > slotSize) {
			throw new RangeError(`item ${item.id} is too large for slot size ${slotSize}`);
		}
		const slot = slots.find((s) => s.remaining >= item.size);
		if (slot) {
			slot.remaining -= item.size;
			slot.ids.push(item.id);
		} else {
			slots.push({ remaining: slotSize - item.size, ids: [item.id] });
		}
	}
	return slots.map((s) => s.ids);
}

