node --input-type=module -e "
import { packSlots } from './src/slot-pack.js';
import assert from 'node:assert/strict';

// R2: equal sizes -> ascending id
assert.deepEqual(packSlots([{id:'z',size:2},{id:'a',size:2},{id:'m',size:2}], 3), [['a','m'],['z']]);

// R1: exact fit
assert.deepEqual(packSlots([{id:'x',size:5}], 5), [['x']]);

// R5: too large -> RangeError naming first in placement order only
const big = [{id:'small',size:99},{id:'bigger',size:50}];
try { packSlots(big, 10); assert.fail('no throw'); }
catch (e) {
  assert.ok(e instanceof RangeError);
  assert.ok(e.message.includes('bigger'));
  assert.ok(!e.message.includes('small'));
  console.log('msg:', e.message);
}

// R6: input not modified
const items = [{id:'a',size:2},{id:'b',size:5}];
const before = JSON.stringify(items);
packSlots(items, 6);
assert.equal(JSON.stringify(items), before);

// R7
assert.deepEqual(packSlots([], 10), []);
console.log('all edge checks passed');
"

