import { packSlots } from './src/slot-pack.js';
import assert from 'node:assert/strict';

// R2: equal sizes -> ascending id
assert.deepEqual(packSlots([{id:'z',size:2},{id:'a',size:2},{id:'m',size:2}], 3), [['a'],['m'],['z']]);
assert.deepEqual(packSlots([{id:'z',size:2},{id:'a',size:2},{id:'m',size:2}], 4), [['a','m'],['z']]);

// R1: exact fit
assert.deepEqual(packSlots([{id:'x',size:5}], 5), [['x']]);

// R5: two too-large items -> RangeError names only the first in placement order (largest size)
const big = [{id:'alpha',size:99},{id:'beta',size:50}];
try { packSlots(big, 10); assert.fail('no throw'); }
catch (e) {
  assert.ok(e instanceof RangeError);
  assert.ok(e.message.includes('alpha'));
  assert.ok(!e.message.includes('beta'));
  console.log('msg:', e.message);
}
// tie in size: first by ascending id
try { packSlots([{id:'y',size:50},{id:'w',size:50}], 10); assert.fail('no throw'); }
catch (e) {
  assert.ok(e instanceof RangeError);
  assert.ok(e.message.includes('w'));
  assert.ok(!e.message.includes('y'));
}

// R6: input not modified
const items = [{id:'a',size:2},{id:'b',size:5}];
const before = JSON.stringify(items);
packSlots(items, 6);
assert.equal(JSON.stringify(items), before);

// R7
assert.deepEqual(packSlots([], 10), []);
console.log('all edge checks passed');
"
